            continue
        occupied = [c for c, value in enumerate(row) if value != bg]
        if not occupied:
            continue
        # Fill the gap between the edge-reaching horizontal stroke and its
        # separated continuation.
        left_end = 0
        while left_end + 1 < w and row[left_end + 1] != bg:
            left_end += 1
        right_start = next((c for c in range(left_end + 1, w)
                            if row[c] != bg), None)
        if right_start is not None and right_start > left_end + 1:
            for c in range(left_end + 1, right_start):
                out[r][c] = 4

    return out
